from taf.ul.ettf.ta_matchers.matchers import MatchingError, MatchingResult, Mismatch
from taf.ul.ettf.logger import custom_logger


logger = custom_logger('NonOrderedMatcher')


class PartialMatch(MatchingResult):
    def __init__(self):
        super(PartialMatch, self).__init__(mismatches=[])

    def __bool__(self):
        return False

    __nonzero__ = __bool__


class NonOrderedMatcher(object):
    def __init__(self, *matchers):
        self._matchers = list(matchers)

    @property
    def matchers(self):
        return self._matchers

    def get_name(self):
        return 'Without order'

    def append_callback(self, callback):
        for m in self._matchers:
            m.append_callback(callback)

    def __eq__(self, other):
        if not hasattr(other, 'matchers'):
            return False
        return self._matchers == other.matchers

    def match(self, packet):
        matching_result = self(packet)
        if not matching_result:
            raise MatchingError(matching_result.mismatches)

    def __call__(self, packet):
        local_mismatches = []

        if self._no_matchers_left():
            raise MatchingError([Mismatch('Matcher is empty!')])

        for matcher in self._matchers:
            try:
                matcher.match(packet)
                self._packet_matched(matcher)
                break
            except MatchingError as error:
                local_mismatches.append(error.mismatches)

        if self._no_matchers_left():
            return MatchingResult([])

        return MatchingResult(local_mismatches) if local_mismatches else PartialMatch()

    def _packet_matched(self, matcher):
        self._matchers.remove(matcher)

    def _no_matchers_left(self):
        return not self._matchers
